export function toCanonical(legacy) {              // legacy wire shape -> canonical
  const { order_id: id, sku, qty, currency, ...rest } = legacy;
  if (currency && currency !== 'EUR') throw new InvalidMessage('currency');
  if (!Number.isInteger(qty) || qty <= 0) throw new InvalidMessage('qty');
  return { id, sku: String(sku).trim().toUpperCase(), quantity: qty };
}
